/* POV label -> character display name (for faces + character cards).
   A chapter label is "Bran III" or "Prologue - Will"; povCharacter() resolves it. */
const POV_CHARS = {
  "Bran": "Bran Stark", "Catelyn": "Catelyn Stark", "Daenerys": "Daenerys Targaryen",
  "Eddard": "Eddard Stark", "Jon": "Jon Snow", "Arya": "Arya Stark", "Tyrion": "Tyrion Lannister",
  "Sansa": "Sansa Stark", "Alayne": "Sansa Stark", "Davos": "Davos Seaworth", "Theon": "Theon Greyjoy",
  "Reek": "Theon Greyjoy", "Jaime": "Jaime Lannister", "Samwell": "Samwell Tarly",
  "Cersei": "Cersei Lannister", "Brienne": "Brienne of Tarth", "Asha": "Asha Greyjoy",
  "Aeron": "Aeron Greyjoy", "Areo": "Areo Hotah", "Arys": "Arys Oakheart",
  "Victarion": "Victarion Greyjoy", "Arianne": "Arianne Martell", "Quentyn": "Quentyn Martell",
  "Connington": "Jon Connington", "Melisandre": "Melisandre", "Barristan": "Barristan Selmy",
  "Will": "Will of the Night's Watch", "Cressen": "Maester Cressen", "Chett": "Chett",
  "Pate": "Pate, the Citadel novice", "Varamyr": "Varamyr Sixskins", "Merrett": "Merrett Frey",
  "Kevan": "Kevan Lannister",
};
function povCharacter(label) {
  const parts = label.split(String.fromCharCode(183)); const name = parts.length > 1 ? parts[1].trim() : label.split(" ")[0];
  return POV_CHARS[name] || name;
}
